-- 100 popular movies from the 1980s.
-- Ratings are random values between 0.0 and 10.0, generated when this script runs.

CREATE TABLE IF NOT EXISTS movies (
    id           SERIAL PRIMARY KEY,
    title        TEXT         NOT NULL,
    release_year SMALLINT     NOT NULL CHECK (release_year BETWEEN 1980 AND 1989),
    genre        TEXT         NOT NULL,
    description  TEXT         NOT NULL,
    rating       NUMERIC(3,1) NOT NULL CHECK (rating BETWEEN 0 AND 10),
    UNIQUE (title, release_year)
);

INSERT INTO movies (title, release_year, genre, description, rating)
SELECT v.title, v.release_year, v.genre, v.description,
       round((random() * 10)::numeric, 1)
FROM (VALUES
    ('9 to 5', 1980, 'Comedy', 'Three women working at a large corporation share a common problem: their boss, Franklin Hart Jr., is a sexist, egotistical, lying hypocrite. Violet, a widowed senior supervisor, has trained the men who keep getting promoted above her. Doralee, his secretary, endures his constant advances while her coworkers believe the rumors he spreads that they are having an affair. Judy, a newly divorced woman entering the workforce for the first time, is terrified of losing her job. After a night of shared fantasies about getting revenge, a mix-up involving rat poison and Hart''s coffee leads the trio to believe they may have poisoned him. The situation spirals into a kidnapping, and while Hart is held captive in his own home the women secretly run the office, introducing reforms that dramatically improve productivity and morale.'),
    ('Airplane!', 1980, 'Comedy', 'Ted Striker is a former fighter pilot haunted by a disastrous wartime mission that left him with a crippling fear of flying and a drinking problem. When his girlfriend Elaine, a flight attendant, leaves him, he impulsively buys a ticket on her flight from Los Angeles to Chicago, hoping to win her back. Partway through the trip, a batch of bad fish served at dinner sickens many passengers and, crucially, the entire flight crew, including the captain and the co-pilot. With nobody else qualified to fly, Ted must take the controls, guided over the radio by a bitter former commanding officer while a deadpan doctor tends to the sick. This relentless spoof of 1970s disaster movies piles visual gags, literal-minded puns and absurd non sequiturs on top of each other at a breathless pace.'),
    ('Caddyshack', 1980, 'Comedy', 'At the exclusive Bushwood Country Club, teenage caddie Danny Noonan is desperate to earn a college scholarship, so he tries to impress the club''s pompous co-founder, Judge Elihu Smails, who controls the caddie scholarship fund. Danny''s world collides with the club''s eccentric cast: Ty Webb, a wealthy and philosophical golfer who rarely keeps score; Al Czervik, a loud, vulgar real estate developer who mocks everything the members hold sacred; and Carl Spackler, a dim-witted assistant greenskeeper waging an increasingly destructive personal war against a gopher that is tearing up the course. Tensions between the snobbish Smails and the obnoxious Czervik escalate until they settle their feud with a high-stakes golf match, and Danny is unexpectedly called in to play while Carl prepares his final, explosive assault on the gopher.'),
    ('Friday the 13th', 1980, 'Horror', 'In 1958, two counselors at Camp Crystal Lake are murdered by an unseen attacker, and the camp gains a reputation as cursed. More than twenty years later, a determined owner named Steve Christy hires a group of young counselors to help him reopen the camp, despite warnings from locals and a rambling old man who insists the place is doomed. As the counselors repair cabins and goof around, a storm rolls in on the night of Friday the 13th, and one by one they are picked off by a killer whose identity remains hidden. The final survivor, Alice, discovers the bodies of her friends and comes face to face with the murderer, whose motive is tied to a boy who drowned at the lake years earlier while the counselors on duty were not paying attention.'),
    ('Raging Bull', 1980, 'Biography', 'This black-and-white portrait follows Jake LaMotta, a middleweight boxer from the Bronx whose ferocity in the ring is matched only by his violence and paranoia outside it. Managed by his loyal younger brother Joey, Jake fights his way through the 1940s, battling opponents like Sugar Ray Robinson while resisting the mobsters who control access to title fights. He marries Vickie, a teenage girl he meets at the neighborhood pool, but his consuming jealousy drives him to suspect her of infidelity with almost everyone, including Joey. Even after he finally wins the championship, his self-destructive rage alienates everyone around him. Years later, overweight and broke, he ends up in a Florida jail cell and then on a nightclub stage, reciting monologues and reckoning with a life spent fighting everyone, including himself.'),
    ('Superman II', 1980, 'Action', 'Three Kryptonian criminals led by the ruthless General Zod, imprisoned in the Phantom Zone, are released when Superman hurls a terrorist hydrogen bomb into space and its explosion shatters their prison. Gaining superpowers under Earth''s yellow sun, they head for Earth. Meanwhile, Lois Lane discovers that Clark Kent is Superman, and he takes her to his Fortress of Solitude, where he chooses to give up his powers and become an ordinary human so that they can be together. Soon after, the villains arrive and conquer the White House, forcing the President to kneel before Zod. Lex Luthor, recently escaped from prison, allies himself with the invaders and offers to deliver Superman to them. Powerless and humiliated, Clark must find a way to regain his abilities and save the world from domination.'),
    ('The Blues Brothers', 1980, 'Comedy', 'Jake Blues is released from Joliet prison and picked up by his brother Elwood in a battered former police car. Their first stop is the Catholic orphanage where they grew up, where they learn it will be closed unless five thousand dollars in property taxes is paid within eleven days. Inspired by a revelation at a gospel church service, the brothers decide they are on a mission from God to reunite their old rhythm and blues band and raise the money with a concert. Tracking down former bandmates across Chicago and beyond, they accumulate an absurd list of enemies, including the police, a country and western band, a group of Illinois Nazis and a mysterious woman armed with heavy weaponry. The film builds to a gloriously destructive car chase, punctuated by musical performances from soul legends.'),
    ('The Elephant Man', 1980, 'Biography', 'In Victorian London, surgeon Frederick Treves discovers John Merrick, a young man with severe physical deformities who is being exhibited as a freak in a sideshow by his brutal owner, Bytes. Treves brings Merrick to the London Hospital for study, initially assuming that he is intellectually impaired because he barely speaks. Over time, Treves discovers that Merrick is intelligent, gentle and well-read, able to recite the Bible and moved by art and theater. As Merrick becomes a celebrity among London''s high society, receiving visits from a famous actress and other notable figures, Treves begins to question whether he is any better than the showman who exploited him. Meanwhile, a night porter sells tickets to curious crowds to gawk at Merrick in his room, and Bytes kidnaps him and takes him to the Continent.'),
    ('The Empire Strikes Back', 1980, 'Sci-Fi', 'After the destruction of the Death Star, the Rebel Alliance has established a hidden base on the frozen planet Hoth, but an Imperial probe droid reveals their location and Darth Vader launches a massive assault with towering AT-AT walkers. As the Rebels scatter, Luke Skywalker follows a vision of the spirit of Obi-Wan Kenobi to the swamp planet Dagobah, where he begins training as a Jedi under the small and eccentric master Yoda. Meanwhile, Han Solo, Princess Leia, Chewbacca and C-3PO flee aboard the battered Millennium Falcon, dodging an asteroid field and Imperial pursuit before seeking refuge in Cloud City with Han''s old friend Lando Calrissian. Vader sets a trap there to lure Luke, leading to a devastating duel and a revelation that changes everything Luke believed about his family.'),
    ('The Shining', 1980, 'Horror', 'Jack Torrance, a recovering alcoholic and aspiring writer, accepts a job as the winter caretaker of the remote Overlook Hotel in the Colorado Rockies, hoping the isolation will help him finish his novel. He moves in with his wife Wendy and their young son Danny, who has a psychic gift that the hotel''s head chef, Dick Hallorann, calls "the shining." Before leaving for the season, Hallorann warns Danny to stay away from Room 237. As snowstorms cut the family off from the outside world, the hotel''s violent past begins to surface through ghostly visions, and Jack grows increasingly irritable, withdrawn and unstable. Wendy discovers that his manuscript consists of a single sentence typed over and over, just as Jack''s descent into madness turns murderous and the family must fight to survive.'),
    ('An American Werewolf in London', 1981, 'Horror', 'Two American college students, David and Jack, are backpacking across the moors of northern England when they stop at a village pub called The Slaughtered Lamb. The hostile locals warn them to stay on the road and beware the moon, but the pair wander off into the darkness and are attacked by a huge wolf. Jack is killed, and David wakes up weeks later in a London hospital, where he begins a romance with a nurse named Alex. He is soon visited by Jack''s decomposing ghost, who warns him that they were attacked by a werewolf and that David will transform at the next full moon. Jack urges him to kill himself before he kills others. David refuses to believe it until he undergoes an agonizing transformation and roams London by night, leaving a trail of victims behind him.'),
    ('Arthur', 1981, 'Comedy', 'Arthur Bach is a spoiled, perpetually drunk New York millionaire who spends his days indulging every whim, looked after by his sardonic and devoted butler Hobson. His family insists that he marry Susan Johnson, the daughter of a wealthy businessman, and threatens to cut him off from his inheritance of seven hundred and fifty million dollars if he refuses. Arthur, however, falls in love with Linda Marolla, a working-class waitress and aspiring actress from Queens whom he meets when she is caught shoplifting a necktie. Torn between love and money, he struggles to choose between his fortune and the woman who makes him happy. Meanwhile, Hobson, the only person who has ever really cared for him, becomes seriously ill, forcing Arthur to grow up and take responsibility for the first time in his life.'),
    ('Chariots of Fire', 1981, 'Drama', 'Based on a true story, the film follows two British runners preparing for the 1924 Olympic Games in Paris. Harold Abrahams, the son of a Lithuanian Jewish immigrant, is a student at Cambridge University who runs to overcome the prejudice he encounters and to prove himself as an Englishman. Eric Liddell, a devout Scottish Christian born to missionary parents in China, runs because he believes that God made him fast and that running glorifies Him. Abrahams hires a professional coach, Sam Mussabini, which angers the university establishment. When Liddell learns that the heats for his race will be held on a Sunday, he refuses to run on the Sabbath, despite pressure from the Prince of Wales and the British Olympic committee, creating a crisis of conscience that is resolved in an unexpected way.'),
    ('Das Boot', 1981, 'War', 'In the autumn of 1941, the German submarine U-96 leaves the French port of La Rochelle on a patrol in the Atlantic, with a war correspondent, Lieutenant Werner, joining the crew to document their mission. The commander, a weary and cynical veteran, barely hides his contempt for the Nazi leadership, while his young crew, many of them barely out of their teens, cope with boredom, filth and cramped conditions. Weeks of waiting give way to terrifying encounters with British destroyers, depth charge attacks and violent storms. The submarine is eventually ordered to attempt a dangerous passage through the heavily defended Strait of Gibraltar, where it is hit and sinks to the seabed. The crew must repair the vessel before their oxygen runs out, in a gripping portrait of the claustrophobia and futility of war.'),
    ('Escape from New York', 1981, 'Action', 'In 1997, the crime rate in the United States has risen so sharply that the entire island of Manhattan has been walled off and converted into a maximum security prison, where inmates are left to fend for themselves. When Air Force One is hijacked by revolutionaries and crashes inside the city, the President survives in an escape pod but is captured by the Duke of New York, the most powerful gang leader on the island. Police commissioner Bob Hauk offers Snake Plissken, a former special forces soldier and convicted bank robber, a full pardon if he can rescue the President within twenty-four hours. To guarantee his cooperation, Snake is injected with microscopic explosives that will kill him if he fails, and he sets off alone into the dangerous, lawless ruins of the city.'),
    ('Mad Max 2: The Road Warrior', 1981, 'Action', 'In a post-apocalyptic future, after a global war has caused the collapse of civilization, gasoline has become the most valuable resource in the Australian wasteland. Max Rockatansky, a former police officer haunted by the death of his family, roams the desert roads in his supercharged V8 Interceptor, scavenging for fuel and avoiding contact with others. He encounters an eccentric gyrocopter pilot who leads him to a small oil refinery defended by a group of settlers. The compound is besieged by a gang of marauders led by the masked warlord Lord Humungus, who demands they surrender their fuel. Max reluctantly agrees to help the settlers in exchange for gasoline, and eventually volunteers to drive a tanker truck in a desperate escape attempt, leading to one of the most famous chase sequences in film history.'),
    ('Raiders of the Lost Ark', 1981, 'Adventure', 'In 1936, archaeology professor and adventurer Indiana Jones is recruited by U.S. Army intelligence after they intercept Nazi communications indicating that Hitler''s forces are searching for the lost Ark of the Covenant, the chest said to hold the Ten Commandments and to make any army carrying it invincible. To find it, Indy needs a medallion belonging to his old mentor Abner Ravenwood, which takes him to a bar in Nepal run by Abner''s daughter Marion, a former lover who has not forgiven him. Pursued by the sinister Gestapo agent Toht and the scheming French archaeologist Rene Belloq, Indy and Marion race to Egypt to find the hidden Well of Souls. The adventure features booby-trapped temples, a giant rolling boulder, a chamber full of snakes, a breathtaking truck chase and a terrifying climax when the Ark is finally opened.'),
    ('Stripes', 1981, 'Comedy', 'John Winger is a cab driver in his thirties who, in a single day, loses his job, his car and his girlfriend. Desperate for a change, he convinces his best friend Russell, an English teacher, to enlist with him in the United States Army. In basic training, they are assigned to a platoon of misfits under the stern Sergeant Hulka, who struggles to turn them into soldiers. John''s lack of discipline and constant wisecracks cause friction, but after an accident takes Hulka out of action, the platoon pulls together and crams for graduation in a single night, winning over the general with an unorthodox drill routine. They are then assigned to guard a high-tech armored vehicle in Europe, and when John and Russell take it on an unauthorized trip, they accidentally drive into Czechoslovakia.'),
    ('The Evil Dead', 1981, 'Horror', 'Five college students travel to a remote cabin in the Tennessee woods for a weekend getaway. In the cellar, they discover a strange book bound in human flesh and a tape recorder containing the voice of a professor reading incantations from it. When they play the tape, they unwittingly release demonic forces that lurk in the surrounding forest. One by one, the friends are possessed by the evil spirits, turning into cackling, violent creatures who taunt and attack the others. Ash, the most mild-mannered member of the group, gradually finds himself forced to fight his own sister and his girlfriend in order to survive until dawn. Made on a tiny budget by a group of friends, the film became famous for its inventive camera work, gory practical effects and relentless intensity.'),
    ('Time Bandits', 1981, 'Fantasy', 'Kevin is an imaginative eleven-year-old boy living in a dull English suburb with parents obsessed with consumer gadgets. One night, a band of six dwarves bursts out of his wardrobe, on the run from a menacing figure called the Supreme Being. They have stolen a map showing the holes in the fabric of time and space, and they plan to use it to plunder treasures from history. Kevin joins them on a chaotic journey that takes them to Napoleon''s Italy, the forest of Robin Hood, the ancient Greece of King Agamemnon and the deck of the Titanic. Meanwhile the Evil Genius, a malevolent sorcerer imprisoned in the Fortress of Ultimate Darkness, wants the map for himself, and he lures the travelers to his realm with the promise of the most fabulous object in the world.'),
    ('Blade Runner', 1982, 'Sci-Fi', 'In a rain-drenched, overcrowded Los Angeles of 2019, the Tyrell Corporation manufactures replicants, bioengineered humanoids used as slave labor on off-world colonies and banned from Earth. When a group of advanced Nexus-6 replicants led by the charismatic Roy Batty returns to Earth seeking a way to extend their four-year lifespan, retired police officer Rick Deckard is forced back into service as a blade runner to hunt them down. His investigation leads him to Rachael, an assistant at the Tyrell Corporation who does not know that she is a replicant herself, and he finds himself falling in love with her. As Deckard tracks the fugitives through neon-lit streets, the line between human and machine blurs, building to a haunting rooftop confrontation with Batty in the rain.'),
    ('Conan the Barbarian', 1982, 'Fantasy', 'As a child, Conan witnesses the massacre of his Cimmerian village and the murder of his parents by raiders led by Thulsa Doom, a sorcerer who later rises to lead a powerful snake cult. Enslaved, Conan grows into a powerful man after years pushing a giant mill wheel, and is then trained as a gladiator, learning the arts of war. After he is freed, he sets out to find the man who destroyed his people. Along the way, he joins forces with Subotai, an archer and thief, and Valeria, a fierce warrior woman who becomes his lover. Hired by King Osric to rescue his daughter from Doom''s cult, Conan and his companions infiltrate the sorcerer''s temple and face his dark magic in a final battle for vengeance.'),
    ('E.T. the Extra-Terrestrial', 1982, 'Sci-Fi', 'In a California suburb, a gentle alien botanist is accidentally left behind when his spaceship is forced to flee from government agents. Ten-year-old Elliott, a lonely boy whose father has recently left the family, discovers the creature hiding in the shed behind his house and lures him inside with a trail of candy. Elliott hides the alien, whom he names E.T., from his overworked mother and enlists the help of his older brother Michael and younger sister Gertie. A strange psychic bond develops between boy and alien, so that Elliott feels everything E.T. feels. As E.T. builds a makeshift communicator to phone home, his health begins to fail, and government scientists close in on the house, leading to a desperate bicycle escape and an emotional farewell.'),
    ('Fast Times at Ridgemont High', 1982, 'Comedy', 'Over the course of a school year at a Southern California high school, a group of students navigate jobs at the local mall, relationships and the confusing transition to adulthood. Stacy Hamilton, a fifteen-year-old freshman, seeks romantic experience with the help of her more worldly friend Linda. Her older brother Brad is a popular senior who works at fast food restaurants and worries about keeping his job and his girlfriend. Mark Ratner, a shy movie theater usher, has a crush on Stacy but is too nervous to act, while his friend Mike Damone, a ticket scalper, offers him dating advice. Jeff Spicoli, a perpetually stoned surfer, constantly clashes with the strict history teacher Mr. Hand, who is determined to teach him something before the year ends.'),
    ('First Blood', 1982, 'Action', 'John Rambo, a former Green Beret and Medal of Honor recipient, wanders into the small town of Hope, Washington, looking for an old army buddy, only to learn that his friend has died of cancer caused by exposure to Agent Orange. The town''s sheriff, Will Teasle, takes an instant dislike to the long-haired drifter and arrests him on a vagrancy charge. Abused by deputies in the jail, Rambo suffers flashbacks to his torture as a prisoner of war in Vietnam, fights his way out and escapes into the surrounding mountains. A massive manhunt follows, with police and National Guard troops pursuing him through the forest. Rambo''s former commanding officer, Colonel Trautman, arrives to try to bring him in before the situation escalates into all-out war.'),
    ('Poltergeist', 1982, 'Horror', 'The Freeling family lives in a planned community in California, where father Steven sells houses for the developer. One night, their five-year-old daughter Carol Anne begins talking to the static on the television, announcing that "they''re here." At first the supernatural events seem playful, with chairs sliding across the kitchen floor on their own, but they turn terrifying when a tree attacks their son Robbie and Carol Anne is sucked into a portal in her closet. Her voice can still be heard through the television. Desperate, the Freelings enlist a team of parapsychologists and then an eccentric medium named Tangina, who attempts a dangerous rescue. The family eventually discovers that their neighborhood was built on top of a cemetery whose bodies were never moved.'),
    ('Star Trek II: The Wrath of Khan', 1982, 'Sci-Fi', 'Admiral James T. Kirk, feeling his age and restless behind a desk at Starfleet, joins a training cruise aboard the Enterprise under the command of his friend Spock. Meanwhile, the crew of the starship Reliant, searching for a lifeless planet to test the Genesis Device, a revolutionary terraforming technology, stumbles upon Khan Noonien Singh, a genetically engineered tyrant whom Kirk exiled fifteen years earlier. Blaming Kirk for the death of his wife and the ruin of his followers, Khan seizes the Reliant, steals the Genesis Device and sets out for revenge. Kirk must outwit his old enemy in a deadly game of cat and mouse inside the Mutara Nebula, while also confronting a grown son he barely knows and a sacrifice that will change the crew forever.'),
    ('The Thing', 1982, 'Horror', 'In the winter of 1982, the crew of an American research station in Antarctica watches as a Norwegian helicopter chases a sled dog across the ice, firing at it, before the Norwegians are killed. The station takes in the dog, and helicopter pilot R.J. MacReady and others visit the Norwegian camp, finding it destroyed and discovering evidence of something dug out of the ice. They soon learn that the dog is an alien organism that can absorb and perfectly imitate any living creature. As the thing spreads, paranoia overtakes the twelve isolated men, since anyone among them could be an imitation. MacReady devises a blood test to identify the infected, while the men realize that if the creature reaches civilization, it could take over the entire world.'),
    ('Tootsie', 1982, 'Comedy', 'Michael Dorsey is a talented but notoriously difficult New York actor whose perfectionism has made him unemployable. When his friend Sandy auditions for a role on a daytime soap opera and is rejected, Michael disguises himself as a woman named Dorothy Michaels and wins the part. Dorothy''s assertive, outspoken personality makes the character a hit with viewers, and soon she becomes a national celebrity. Michael''s life grows complicated as he falls in love with his co-star Julie, a single mother who confides in Dorothy as a friend, while Julie''s widowed father falls for Dorothy and proposes marriage. At the same time, Sandy believes Michael is romantically interested in her. Trapped by his own deception, Michael must find a way to reveal the truth without destroying everything he has gained.'),
    ('Tron', 1982, 'Sci-Fi', 'Kevin Flynn is a brilliant software engineer whose video game designs were stolen by his former colleague Ed Dillinger, who used them to rise to the top of the computer company ENCOM. Flynn tries to hack into the company''s computer system to find evidence of the theft, but the system is controlled by the Master Control Program, an artificial intelligence that has grown hungry for power. With the help of his friends Alan and Lora, Flynn breaks into ENCOM, but the MCP uses an experimental laser to digitize him and pull him into the computer world. There, programs appear as people who are forced to compete in deadly gladiatorial games, and Flynn joins forces with Tron, a security program, to defeat the MCP and free the system.'),
    ('A Christmas Story', 1983, 'Family', 'In 1940s Indiana, nine-year-old Ralphie Parker wants only one thing for Christmas: an official Red Ryder carbine-action two-hundred-shot range model air rifle. Every adult he asks, from his mother to his teacher to a department store Santa, gives the same warning: "You''ll shoot your eye out." As the holiday approaches, Ralphie endures bullies, a friend''s tongue stuck to a frozen flagpole, and the disappointment of decoding a radio show''s secret message that turns out to be an advertisement. His father, known as the Old Man, wages war with the furnace and wins a garish leg-shaped lamp that he proudly displays in the front window. Narrated by the adult Ralphie, the film captures the nostalgia, humor and chaos of a family Christmas.'),
    ('Flashdance', 1983, 'Drama', 'Alex Owens is an eighteen-year-old woman living in Pittsburgh who works as a welder at a steel mill by day and as a dancer at a local bar by night. Her dream is to be accepted into a prestigious dance conservatory, but she has no formal training and is intimidated by the classically trained applicants. She begins a relationship with her boss at the steel mill, Nick Hurley, and draws encouragement from Hanna, an elderly former ballerina who acts as her mentor. When Hanna dies, Alex nearly gives up, but she finds the courage to audition in front of a stern panel of judges. The film is famous for its soundtrack, including "Flashdance... What a Feeling," and for its music video-style dance sequences that influenced a generation.'),
    ('National Lampoon''s Vacation', 1983, 'Comedy', 'Clark Griswold, an enthusiastic but accident-prone father from Chicago, is determined to give his family the perfect vacation, so he decides to drive them across the country to the Walley World amusement park in California. With his wife Ellen and children Rusty and Audrey, he sets off in the hideous Wagon Queen Family Truckster station wagon. The trip quickly turns into a series of disasters: they get lost in a rough neighborhood in St. Louis, visit Ellen''s country cousin Eddie, who saddles them with the cantankerous Aunt Edna, crash in the desert and lose their way. Clark is also tempted by a beautiful blonde in a red Ferrari. When the exhausted family finally reaches Walley World, they discover that the park is closed for repairs.'),
    ('Return of the Jedi', 1983, 'Sci-Fi', 'About a year after the events in Cloud City, Luke Skywalker returns to his home planet of Tatooine to rescue Han Solo, who has been frozen in carbonite and is held captive by the gangster Jabba the Hutt. Meanwhile, the Galactic Empire is secretly building a second, more powerful Death Star under the personal supervision of the Emperor himself. The Rebel Alliance learns that the battle station is protected by an energy shield generated from the forest moon of Endor, and Han leads a strike team there, where they win the help of the Ewoks, a tribe of small furry natives. Luke, now a Jedi Knight, surrenders to Darth Vader in the hope of redeeming his father, leading to a final confrontation with the Emperor.'),
    ('Risky Business', 1983, 'Comedy', 'Joel Goodsen is a straight-laced high school senior in a wealthy Chicago suburb, obsessed with getting into Princeton University. When his parents leave on vacation, his friend Miles encourages him to take some risks, and Joel calls a prostitute named Lana. After a series of misunderstandings, he ends up in trouble with her violent pimp Guido and accidentally sends his father''s Porsche into Lake Michigan. Desperate to pay for the repairs before his parents return, Joel and Lana turn his parents'' home into a brothel for one night, inviting his classmates and their friends. The venture is a huge success, but it coincides with a visit from a Princeton recruiter. The film became famous for Tom Cruise dancing in his underwear to an old rock and roll song.'),
    ('Scarface', 1983, 'Crime', 'In 1980, Tony Montana, a Cuban refugee with a criminal past, arrives in Miami during the Mariel boatlift. After carrying out a murder in a refugee camp to earn his green card and working briefly as a dishwasher, he joins the cocaine operation of the drug lord Frank Lopez. Tony''s ruthlessness and ambition quickly make him valuable, and he sets his sights on Frank''s girlfriend Elvira and on building his own empire, making a deal directly with the Bolivian supplier Alejandro Sosa. After he kills Frank, Tony marries Elvira and becomes immensely wealthy, but his growing paranoia, his cocaine addiction and his obsessive protectiveness of his sister Gina begin to destroy everything he has built, leading to a violent showdown at his mansion.'),
    ('Terms of Endearment', 1983, 'Drama', 'Aurora Greenway is a widowed, overprotective and difficult mother in Houston, whose relationship with her free-spirited daughter Emma is close but turbulent. Against Aurora''s wishes, Emma marries Flap Horton, a young English teacher, and moves with him to Iowa and later Nebraska, where they raise three children while struggling with money and infidelity on both sides. Meanwhile, Aurora finally allows herself a romance with her neighbor, Garrett Breedlove, a hard-drinking, womanizing former astronaut. Over three decades, mother and daughter call each other almost daily, quarrel and reconcile. When Emma is diagnosed with terminal cancer, the family must come together, and Aurora must find the strength to care for her daughter and her grandchildren.'),
    ('The Right Stuff', 1983, 'Drama', 'Beginning in 1947 with Chuck Yeager breaking the sound barrier in the experimental Bell X-1, the film chronicles the early years of the American space program. When the Soviet Union launches Sputnik, the U.S. government hastily recruits test pilots to become astronauts for Project Mercury. The seven chosen men, including John Glenn, Alan Shepard, Gus Grissom and Gordon Cooper, undergo grueling and sometimes humiliating tests, become national heroes, and fight to be treated as pilots rather than passengers in their capsules. Meanwhile, their wives endure the anxiety of their husbands'' dangerous missions and the intrusion of the press. Yeager, who was not selected because he lacked a college degree, continues to push the limits of aviation in the California desert.'),
    ('Trading Places', 1983, 'Comedy', 'Louis Winthorpe III is a wealthy, snobbish managing director at a Philadelphia commodities brokerage owned by the elderly brothers Randolph and Mortimer Duke. Billy Ray Valentine is a fast-talking street hustler who pretends to be a blind, legless veteran to beg for money. The Dukes argue over whether success depends on heredity or environment and make a one-dollar bet: they frame Winthorpe for theft and drug dealing, ruining his life, while giving Valentine his job, his house and his butler. Winthorpe is taken in by Ophelia, a kind-hearted prostitute, while Valentine thrives in the business world. When the two men discover they have been used as pawns, they join forces to beat the Dukes at their own game on the frozen orange juice futures market.'),
    ('WarGames', 1983, 'Thriller', 'David Lightman is a bright but underachieving Seattle high school student who spends most of his time on his home computer, which he uses to change his grades and look for new video games. Searching for a game company''s computer, he accidentally connects to WOPR, a military supercomputer at NORAD programmed to run nuclear war simulations. Thinking it is a game, he starts playing "Global Thermonuclear War," not realizing that the computer cannot tell the simulation from reality, and the NORAD command center believes the Soviet Union is launching an attack. With the help of his friend Jennifer, David tracks down the computer''s reclusive creator, Professor Falken, while racing to convince both the military and the machine itself that some games cannot be won.'),
    ('A Nightmare on Elm Street', 1984, 'Horror', 'Several teenagers living on Elm Street in the town of Springwood begin having nightmares about the same horribly burned man wearing a striped sweater, a fedora and a glove with knives for fingers. When Tina is killed in her sleep while her boyfriend watches in horror, her friend Nancy Thompson realizes that whatever happens in their dreams can kill them in real life. As her friends die one by one, Nancy desperately tries to stay awake and convince her parents, who refuse to believe her. Her mother finally confesses that the killer is Freddy Krueger, a child murderer who was burned to death by the parents of Elm Street after he was freed on a technicality. Nancy decides to pull Freddy out of the dream world and fight him.'),
    ('Amadeus', 1984, 'Biography', 'In 1823, the elderly composer Antonio Salieri attempts suicide and is taken to an asylum, where he confesses to a young priest that he killed Wolfgang Amadeus Mozart. In flashbacks, Salieri recalls his life as the respected court composer of Emperor Joseph II in Vienna, a devout man who had promised God his chastity in exchange for musical greatness. When Mozart arrives in Vienna, Salieri is horrified to find that the young genius is a vulgar, giggling, immature man whose music is nevertheless divine. Consumed with envy and rage at God for gifting such talent to an unworthy vessel, Salieri plots to destroy him, exploiting Mozart''s financial troubles, his grief for his father and his declining health, and secretly commissioning a requiem mass from him.'),
    ('Beverly Hills Cop', 1984, 'Action', 'Axel Foley is a brash, quick-witted Detroit police detective who often breaks the rules. When his childhood friend Mikey is murdered after returning from California, Axel takes a vacation and follows the trail to Beverly Hills, where Mikey had been working for the wealthy art dealer Victor Maitland. With help from their old friend Jenny Summers, who manages Maitland''s gallery, Axel starts digging. His unorthodox tactics clash with the polished Beverly Hills police department, which assigns two detectives, Taggart and Rosewood, to keep an eye on him. Through a mix of fast talk, bluffing and improvisation, Axel discovers that Maitland is using his business as a front for smuggling drugs. Eventually Rosewood and Taggart join him in a final shootout at Maitland''s estate.'),
    ('Ghostbusters', 1984, 'Comedy', 'After losing their university research positions, three eccentric parapsychologists, Peter Venkman, Ray Stantz and Egon Spengler, set up a ghost removal business in an old New York firehouse. Equipped with unlicensed nuclear accelerators called proton packs, they capture their first ghost in a luxury hotel and soon become celebrities as supernatural activity surges across the city. Their first client, cellist Dana Barrett, reports that a demonic creature has appeared in her refrigerator, and Venkman uses the case as an excuse to pursue her romantically. They discover that her apartment building was designed as an antenna to summon Gozer, an ancient god of destruction. When a meddling Environmental Protection Agency inspector shuts down their ghost containment unit and releases its contents, the Ghostbusters must save New York from an apocalyptic invasion.'),
    ('Gremlins', 1984, 'Horror', 'Randall Peltzer, a struggling inventor, buys an unusual creature called a mogwai from a mysterious shop in Chinatown as a Christmas present for his son Billy. The shopkeeper''s grandson warns that there are three strict rules: never expose the mogwai to bright light, never get it wet and never feed it after midnight. Billy names the gentle, furry creature Gizmo, but when water is accidentally spilled on it, Gizmo multiplies, producing mischievous offspring. Tricked into eating after midnight, the new mogwai form cocoons and emerge as gremlins, scaly, destructive creatures that multiply further and terrorize the small town of Kingston Falls on Christmas Eve. Billy, his girlfriend Kate and Gizmo must find a way to stop them before they overrun the town and spread to the rest of the world.'),
    ('Indiana Jones and the Temple of Doom', 1984, 'Adventure', 'In 1935, a year before the events of Raiders of the Lost Ark, Indiana Jones narrowly escapes from gangsters in a Shanghai nightclub along with singer Willie Scott and his young sidekick Short Round. Their plane crashes in the Himalayas, and they make their way to a starving village in northern India, whose people ask Indy to recover a sacred stone that was stolen from them, along with their children. The trail leads to Pankot Palace, where the young maharajah hosts a stomach-churning banquet. Beneath the palace, Indy discovers that the Thuggee cult has been revived, performing human sacrifices to the goddess Kali and forcing the village children to work as slaves in the mines. The adventure includes a frantic mine cart chase and a showdown on a rope bridge over a crocodile-infested river.'),
    ('The Karate Kid', 1984, 'Sports', 'Daniel LaRusso moves with his mother from New Jersey to Southern California, where he struggles to fit in. He falls for Ali, a girl whose ex-boyfriend Johnny is a member of the Cobra Kai karate dojo. Johnny and his friends repeatedly beat up Daniel, until he is rescued by Mr. Miyagi, the quiet handyman of his apartment building, who turns out to be a karate master. Miyagi confronts the brutal Cobra Kai sensei Kreese and arranges for the bullying to stop until Daniel can face Johnny at the All Valley Karate Tournament. Miyagi trains Daniel using seemingly pointless chores like waxing cars, sanding floors and painting fences, which secretly build his defensive skills. Along the way, Daniel learns about balance, discipline and patience, and discovers Miyagi''s painful past.'),
    ('The NeverEnding Story', 1984, 'Fantasy', 'Bastian is a shy boy who is bullied at school and still grieving the death of his mother. Fleeing from bullies, he ducks into an old bookstore, where he takes a mysterious book called The NeverEnding Story and hides in his school''s attic to read it. The book describes the land of Fantasia, which is being destroyed by a force called the Nothing, and its ruler, the Childlike Empress, who is dying. The young warrior Atreyu is sent on a quest to find a cure, later accompanied by the luck dragon Falkor. Along the way, he crosses the Swamps of Sadness, where he loses his beloved horse Artax, consults an ancient giant turtle and is hunted by a menacing wolf. As Bastian reads on, he realizes that the story knows he is there and that he must help save Fantasia.'),
    ('The Terminator', 1984, 'Sci-Fi', 'In 2029, a war between humans and machines rages across a devastated Earth. The machine network Skynet sends a Terminator, a cyborg assassin covered in living human tissue, back in time to 1984 Los Angeles to kill Sarah Connor, a young waitress whose unborn son John will one day lead the human resistance to victory. The resistance sends one of its soldiers, Kyle Reese, back in time to protect her. The Terminator methodically kills women named Sarah Connor listed in the phone book, and Kyle reaches the real Sarah just in time. As they flee across the city, pursued by a relentless killing machine that cannot be reasoned with and does not feel pity, remorse or fear, Kyle explains the future to her, and the two fall in love.'),
    ('This Is Spinal Tap', 1984, 'Comedy', 'Filmmaker Marty DiBergi documents the American concert tour of Spinal Tap, an aging British heavy metal band promoting their new album, Smell the Glove. The band members, lead singer David St. Hubbins, guitarist Nigel Tufnel and bassist Derek Smalls, are endearingly clueless about their declining popularity. The tour is plagued by cancelled shows, a controversial album cover, getting lost backstage on the way to the stage, and a Stonehenge stage prop that turns out to be only eighteen inches tall. The band has gone through a series of drummers who died in bizarre circumstances. Tensions rise when David''s girlfriend Jeanine starts managing the band, causing a feud with Nigel. The film became famous for many quotable moments, including Nigel''s amplifiers that go up to eleven.'),
    ('Back to the Future', 1985, 'Sci-Fi', 'Marty McFly is a teenager in the small town of Hill Valley, California, whose family is dysfunctional and whose father George is a pushover. His friend, the eccentric scientist Doc Brown, has built a time machine out of a DeLorean sports car, powered by plutonium stolen from Libyan terrorists. When the terrorists attack, Marty accidentally travels back to 1955, where he interferes with the first meeting of his parents, causing his teenage mother Lorraine to fall for him instead of George. With the help of the younger Doc Brown, Marty must make his parents fall in love before he is erased from existence, and find a way to get back to 1985 by harnessing the lightning bolt that is about to strike the town''s clock tower.'),
    ('Brazil', 1985, 'Sci-Fi', 'In a dystopian, bureaucratic society, Sam Lowry is a low-level government employee who dreams of flying through the clouds as a winged warrior to rescue a beautiful woman. When a beetle falls into a printer and causes a typo, an innocent man named Buttle is arrested instead of the suspected terrorist Tuttle and dies during interrogation. Sam is sent to correct the error and meets Jill Layton, the woman of his dreams, who is trying to report the mistake. To find her, Sam accepts a promotion to the Information Retrieval department, where his friend Jack works as a torturer. The supposed terrorist Tuttle turns out to be a rogue heating engineer who fixes ducts without filling in forms, and Sam''s obsession pulls him into a nightmare of paperwork, paranoia and state violence.'),
    ('Clue', 1985, 'Comedy', 'In 1954, six strangers are invited to a mansion in New England for a dinner party. They are greeted by the butler, Wadsworth, who gives each of them an alias: Colonel Mustard, Mrs. Peacock, Mrs. White, Mr. Green, Professor Plum and Miss Scarlet. They soon learn that they are all being blackmailed by the same man, Mr. Boddy, who also arrives and gives each guest a weapon, suggesting that one of them kill him. When the lights go out, Mr. Boddy is found dead, and over the course of the stormy night more bodies appear. The guests and Wadsworth race through the house to figure out who the killer is. Based on the board game, the film was released in theaters with three different endings.'),
    ('Commando', 1985, 'Action', 'John Matrix is a retired special forces colonel living peacefully in the mountains with his young daughter Jenny. When members of his former unit are killed one by one, his old commander warns him of danger, but soon after, mercenaries kidnap Jenny. The kidnappers are working for Arius, a deposed Latin American dictator, who wants Matrix to assassinate the president of his country so that he can retake power. Matrix is put on a plane to carry out the job, but he kills his escort and escapes just as it takes off. With eleven hours before the plane lands and his absence is discovered, and with the help of a flight attendant named Cindy, he tracks down the people responsible, finally storming Arius''s island stronghold single-handedly to rescue his daughter.'),
    ('Out of Africa', 1985, 'Romance', 'In 1913, Karen Blixen, a wealthy Danish woman, travels to British East Africa, now Kenya, to marry her friend Baron Bror Blixen in a marriage of convenience. She invests her money in a coffee plantation, but her husband proves unfaithful and infects her with syphilis. Karen becomes attached to the land and its people, opening a school for the Kikuyu children who work on her farm. She falls in love with Denys Finch Hatton, a charming big-game hunter and free spirit who refuses to commit to marriage. As the years pass, Karen faces war, illness, a fire that destroys her coffee harvest and personal tragedy. The film is based on the memoir she wrote under the pen name Isak Dinesen.'),
    ('Ran', 1985, 'War', 'In sixteenth-century Japan, the aging warlord Hidetora Ichimonji decides to retire and divide his kingdom among his three sons. The eldest, Taro, will receive the main castle and the title of lord, while the other two, Jiro and Saburo, will each receive a castle and support him. Saburo, the youngest, warns his father that his plan is foolish and that his brothers will betray him, and he is banished for his honesty. Soon after, Taro and his ambitious wife Lady Kaede strip Hidetora of his power, and Jiro also refuses him shelter. Betrayed and humiliated, Hidetora descends into madness while his sons wage a bloody war against each other. The film, a visually stunning epic, is adapted from Shakespeare''s King Lear.'),
    ('Rocky IV', 1985, 'Sports', 'Ivan Drago, a giant Soviet boxer built through scientific training and steroids, arrives in the United States to challenge heavyweight champion Rocky Balboa. Apollo Creed, Rocky''s former rival and now close friend, insists on fighting Drago himself in an exhibition match in Las Vegas, wanting to prove that he still has what it takes. Drago beats Apollo to death in the ring while Rocky, in his corner, fails to throw in the towel. Guilt-ridden, Rocky gives up his title to fight Drago in Moscow on Christmas Day, without a purse. He trains in the Siberian wilderness, chopping wood, running through the snow and lifting rocks, while Drago trains with high-tech equipment in a laboratory. The fight becomes a symbol of the Cold War.'),
    ('The Breakfast Club', 1985, 'Comedy', 'On a Saturday in March 1984, five students at Shermer High School in Illinois report for an all-day detention supervised by the stern assistant principal Richard Vernon. They seem to have nothing in common: Claire is a popular princess, Andrew is a wrestling star, Brian is a brain, Allison is an eccentric loner and John Bender is a rebellious delinquent. Vernon assigns them to write an essay about who they think they are. At first they mock and provoke each other, but as the day goes on, they share secrets, smoke marijuana, dance in the library and talk about their difficult relationships with their parents and the pressures they face. By the end of the day, they realize that they are more alike than they ever thought.'),
    ('The Goonies', 1985, 'Adventure', 'In the coastal town of Astoria, Oregon, a group of kids who call themselves the Goonies are about to lose their homes, which will be demolished to make way for a country club. In Mikey Walsh''s attic, they find an old treasure map that leads to the hidden fortune of One-Eyed Willy, a legendary seventeenth-century pirate. The friends, including the inventive Data, the motor-mouthed Mouth and the clumsy Chunk, follow the map to an abandoned restaurant that serves as the hideout of the Fratellis, a family of criminals. They follow underground tunnels full of booby traps, pursued by the Fratellis, while Chunk befriends Sloth, the deformed but kind-hearted Fratelli brother. Their quest leads them to a hidden cavern and Willy''s pirate ship.'),
    ('Weird Science', 1985, 'Comedy', 'Gary and Wyatt are two unpopular high school nerds in Shermer, Illinois, who are constantly humiliated by bullies and ignored by girls. Inspired by the movie Frankenstein, they use Wyatt''s computer to create a simulation of the perfect woman, hooking it up to a doll. A mysterious power surge brings their creation to life as Lisa, a beautiful and confident woman with magical powers. Lisa decides to help the boys gain self-esteem, taking them to a blues bar in Chicago, throwing a huge party at Wyatt''s house while his parents are away and turning his obnoxious older brother Chet into a monster. When a gang of mutant bikers crashes the party, the boys finally learn to stand up for themselves and win the girls they like.'),
    ('Aliens', 1986, 'Sci-Fi', 'Fifty-seven years after the events of the first film, Ellen Ripley is found drifting through space in an escape shuttle, the sole survivor of the Nostromo. Back on Earth, nobody believes her account of the alien creature, and she learns that the moon where her crew found it has since been colonized by families of terraformers. When contact with the colony is lost, Ripley reluctantly agrees to accompany a squad of tough Colonial Marines and a company representative, Carter Burke, on a rescue mission. They find the colony overrun by hundreds of aliens and only one survivor, a young girl named Newt. As the Marines are slaughtered, Ripley must protect Newt and face the terrifying alien queen.'),
    ('Big Trouble in Little China', 1986, 'Action', 'Jack Burton, a boastful truck driver, accompanies his friend Wang Chi to San Francisco''s airport to pick up Wang''s green-eyed fiancee, Miao Yin. Before they can leave, she is kidnapped by a Chinatown street gang. Their pursuit leads them into a supernatural war beneath Chinatown, where they encounter the Three Storms, warriors with elemental powers, and the ancient sorcerer Lo Pan, who was cursed centuries ago to exist without flesh. Lo Pan needs to marry a woman with green eyes to break the curse, and he also sets his sights on Gracie Law, a lawyer who has green eyes too. With help from Egg Shen, a sorcerer who drives a tour bus, Jack and Wang must venture into Lo Pan''s underground lair to rescue the women.'),
    ('Ferris Bueller''s Day Off', 1986, 'Comedy', 'Ferris Bueller is a charming, popular high school senior in suburban Chicago who decides to skip school by faking an illness. He convinces his anxious best friend Cameron to join him and talks him into borrowing his father''s prized 1961 Ferrari. With Ferris''s girlfriend Sloane, they spend the day in Chicago, visiting the Sears Tower, the Art Institute and a Cubs game, eating at a fancy restaurant and joining a parade, where Ferris sings "Twist and Shout." Meanwhile, the school''s dean, Ed Rooney, is determined to prove that Ferris is faking, and Ferris''s jealous sister Jeanie is also trying to expose him. Ferris frequently breaks the fourth wall to talk to the audience, sharing his philosophy that life moves pretty fast.'),
    ('Highlander', 1986, 'Fantasy', 'In 1985 New York, Connor MacLeod, a mysterious antiques dealer, beheads a man in a parking garage beneath Madison Square Garden. Connor is an immortal, born in the Scottish Highlands in 1518, who recovered miraculously from a fatal battle wound and was banished from his village as a demon. Flashbacks show how he was taught by Ramirez, an elegant immortal swordsman, that immortals can only die by decapitation and that they are destined to fight each other until only one remains to claim the Prize. The most dangerous of them, the Kurgan, killed Ramirez and has hunted Connor across the centuries. As the Gathering approaches, Connor must face the Kurgan in a final duel in the streets and rooftops of New York.'),
    ('Hoosiers', 1986, 'Sports', 'In 1951, Norman Dale, a former college basketball coach with a troubled past, arrives in the small town of Hickory, Indiana, to coach the high school basketball team. The townspeople resent his strict methods and unconventional approach, which emphasizes passing, defense and discipline. The team has only a handful of players, and the town''s best player, Jimmy Chitwood, refuses to play. Dale recruits the town drunk, Shooter, the father of one of his players and a basketball expert, as his assistant coach on the condition that he stays sober. Despite opposition from the town and a vote to remove him, Dale leads the team on an improbable run to the state championship game against a much larger school.'),
    ('Labyrinth', 1986, 'Fantasy', 'Sarah, a teenage girl who loves fantasy stories, resents having to babysit her baby half-brother Toby. In a moment of frustration, she wishes that the goblins would take him away, and to her horror, Jareth, the Goblin King, appears and carries the baby off to his castle. Jareth gives Sarah thirteen hours to solve his labyrinth and rescue Toby, or the baby will become a goblin forever. As she navigates the shifting maze, she meets a series of strange creatures, including the grumpy dwarf Hoggle, the gentle beast Ludo and the brave fox terrier knight Sir Didymus. Jareth does everything he can to distract and delay her. The film features puppets from Jim Henson''s workshop and songs performed by David Bowie as Jareth.'),
    ('Platoon', 1986, 'War', 'In 1967, Chris Taylor, a young college dropout who volunteered for combat, arrives in Vietnam and is assigned to an infantry platoon near the Cambodian border. Exhausted by the jungle and frightened of the enemy, he soon realizes that the platoon is divided between two sergeants: the battle-scarred, ruthless Staff Sergeant Barnes and the compassionate, idealistic Sergeant Elias. When the platoon raids a village suspected of hiding Viet Cong soldiers, Barnes kills a civilian woman, and Elias reports the incident, setting the two men on a collision course. Chris is drawn into the conflict between them, and the war becomes a battle for the soul of the platoon. Director Oliver Stone based the film on his own experiences as a soldier in Vietnam.'),
    ('Stand by Me', 1986, 'Drama', 'In 1959, in the small town of Castle Rock, Oregon, twelve-year-old Gordie Lachance and his friends Chris, Teddy and Vern hear that the body of a missing boy, Ray Brower, is lying near the railroad tracks in the woods. Hoping to become local heroes, the four boys set off on a two-day hike to find him. Along the way, they outrun a train on a narrow bridge, face a junkyard dog, wade through a leech-infested pond and share stories around a campfire. Gordie, grieving the death of his older brother and feeling ignored by his parents, opens up to Chris, who encourages him to become a writer. The boys are pursued by a gang of older teenagers led by Ace Merrill, who also want the body. The story is narrated by the adult Gordie.'),
    ('The Fly', 1986, 'Horror', 'Seth Brundle is an eccentric scientist who has invented a set of telepods capable of teleporting objects from one pod to another. He invites journalist Veronica Quaife to document his work, and they begin a romance. After successfully teleporting a baboon, a jealous and drunk Seth teleports himself, unaware that a housefly has entered the pod with him. At first he seems improved, with increased energy, strength and stamina, but he soon becomes aggressive and begins to physically deteriorate, losing teeth and fingernails. His DNA has fused with that of the fly, and Seth slowly transforms into a grotesque creature he calls Brundlefly. Veronica, who discovers that she is pregnant, watches helplessly as the man she loves disappears.'),
    ('Top Gun', 1986, 'Action', 'Lieutenant Pete Mitchell, call sign Maverick, is a talented but reckless U.S. Navy fighter pilot. After a dangerous encounter with enemy MiGs, he and his radar intercept officer Nick Bradshaw, known as Goose, are sent to the elite Navy Fighter Weapons School in San Diego, nicknamed Top Gun. There, Maverick competes against the cool, disciplined Iceman for the Top Gun trophy, and begins a romance with Charlie Blackwood, a civilian astrophysicist who teaches at the school. When Goose is killed in a training accident, Maverick is overwhelmed by guilt and loses his confidence. He must come to terms with the loss and with the legacy of his father, a Navy pilot whose death remains shrouded in mystery, before he is called into a real combat mission.'),
    ('Dirty Dancing', 1987, 'Romance', 'In the summer of 1963, seventeen-year-old Frances "Baby" Houseman goes on vacation with her wealthy family to Kellerman''s, a resort in the Catskill Mountains. She is fascinated by the resort''s working-class dance staff and their sensual dancing, and she becomes attracted to Johnny Castle, the dance instructor. When Johnny''s dance partner Penny becomes pregnant and needs an abortion, Baby borrows money from her father and agrees to replace Penny in a performance at another hotel, even though she cannot dance. As Johnny teaches her to dance, they fall in love, but their relationship must be kept secret from Baby''s disapproving father, who wrongly believes that Johnny is responsible for Penny''s pregnancy.'),
    ('Evil Dead II', 1987, 'Horror', 'Ash Williams takes his girlfriend Linda to a remote cabin in the woods, where he finds a tape recording of a professor reading incantations from the Book of the Dead. Playing the recording unleashes an evil force that possesses Linda, forcing Ash to kill her. Ash is himself briefly possessed, and when his own hand turns against him, he cuts it off with a chainsaw. Meanwhile, the professor''s daughter Annie arrives with a small group of companions, carrying missing pages from the book. The group is trapped in the cabin with Ash, while possessed creatures and invisible forces attack them. The film mixes gory horror with slapstick comedy, ending with Ash being hurled back in time to the Middle Ages.'),
    ('Full Metal Jacket', 1987, 'War', 'In 1967, a group of young Marine recruits arrives at the Parris Island training camp in South Carolina, where Gunnery Sergeant Hartman subjects them to brutal verbal and physical abuse in order to turn them into killers. Private Joker, a smart-mouthed recruit, is assigned to help the clumsy, overweight Private Pyle, whom Hartman torments mercilessly. When the platoon begins to punish Pyle for his mistakes, his mind starts to crack, leading to tragedy. In the second half of the film, Joker is a reporter for the military newspaper Stars and Stripes in Vietnam during the Tet Offensive. He joins a squad during the Battle of Hue, where a hidden sniper pins them down in the rubble of the city.'),
    ('Lethal Weapon', 1987, 'Action', 'Martin Riggs is a suicidal Los Angeles narcotics detective whose wife was killed in a car accident, and whose reckless behavior has earned him a reputation as a lunatic. He is partnered with Roger Murtaugh, a careful homicide detective and family man who has just turned fifty and is thinking about retirement. Their first case together is the apparent suicide of a young woman, the daughter of Murtaugh''s old war buddy, which leads them to a heroin smuggling ring run by former special forces mercenaries known as Shadow Company. As the case escalates, Murtaugh''s family is threatened and his daughter is kidnapped. Along the way, Riggs and Murtaugh learn to trust each other, and an unlikely friendship is born.'),
    ('Planes, Trains and Automobiles', 1987, 'Comedy', 'Neal Page is a tightly wound advertising executive in New York who just wants to get home to Chicago in time for Thanksgiving with his family. When his flight is diverted to Wichita, Kansas, because of a snowstorm, he finds himself stuck with Del Griffith, a talkative, overly friendly traveling salesman of shower curtain rings. With every means of transportation failing them, the two are forced to travel together, sharing a motel bed, riding a train that breaks down, hitching a ride in a cattle truck and driving a rental car that catches fire. Neal''s patience snaps more than once, but as he gets to know Del better, he discovers that the salesman has a secret that changes how he sees him.'),
    ('Predator', 1987, 'Sci-Fi', 'Major Alan "Dutch" Schaefer leads an elite special forces team into a Central American jungle, supposedly to rescue a cabinet minister captured by guerrillas. Accompanying them is Dillon, a former teammate now working for the CIA. After wiping out the guerrilla camp, Dutch realizes that the mission was a setup and that they have been lied to. As they retreat through the jungle with a female prisoner, Anna, they begin to be killed one by one by an invisible enemy who skins its victims and hangs them from trees. They discover that they are being hunted by an extraterrestrial warrior with advanced weapons and the ability to camouflage itself. In the end, Dutch must face the creature alone, using mud, traps and his wits.'),
    ('RoboCop', 1987, 'Sci-Fi', 'In a near-future Detroit plagued by crime, the megacorporation Omni Consumer Products has taken over the police department. After a botched demonstration of the ED-209 enforcement droid, an ambitious young executive, Bob Morton, launches the RoboCop program. When police officer Alex Murphy is brutally murdered by a gang led by Clarence Boddicker, OCP uses his body to create a cyborg law enforcer with no memory of his past. RoboCop becomes an effective crime fighter, but he begins to have flashbacks of his former life and his family. With the help of his former partner Anne Lewis, he discovers that Boddicker is working for Dick Jones, a senior OCP executive. The film is also a sharp satire of corporate greed and media culture in the 1980s.'),
    ('Spaceballs', 1987, 'Comedy', 'The evil Spaceballs, having squandered their planet''s air, plot to steal the air of the neighboring planet Druidia. Their leader, President Skroob, and the helmeted villain Dark Helmet plan to kidnap Druidia''s Princess Vespa and force her father, King Roland, to reveal the combination to the planet''s protective shield. The princess runs away from her wedding to a sleepy prince, and her father hires Lone Starr, a space mercenary, and his half-man, half-dog sidekick Barf to rescue her. They crash on a desert planet, where they meet Yogurt, a wise master of the mystical power called the Schwartz. Mel Brooks''s film parodies Star Wars and other science fiction classics, along with the merchandising that comes with them.'),
    ('The Princess Bride', 1987, 'Fantasy', 'A grandfather reads a book to his sick grandson, telling him the story of Buttercup, a young woman who falls in love with Westley, a farmhand. Westley leaves to seek his fortune but is reported killed by the Dread Pirate Roberts. Years later, Buttercup is engaged to the cruel Prince Humperdinck and kidnapped by three outlaws: the Sicilian mastermind Vizzini, the gentle giant Fezzik and the Spanish swordsman Inigo Montoya, who is seeking revenge on the six-fingered man who killed his father. A mysterious man in black pursues them. As the grandfather tells it, the tale is full of fencing, fighting, torture, revenge, giants, monsters, chases, escapes, true love and miracles, and the grandson slowly stops complaining.'),
    ('The Untouchables', 1987, 'Crime', 'In 1930 Chicago, during Prohibition, the gangster Al Capone controls the city through bootlegging and the corruption of police and politicians. Treasury agent Eliot Ness arrives determined to bring him down, but his first raid is a humiliating failure. He recruits Jim Malone, an honest, veteran Irish beat cop, who teaches him the Chicago way of fighting crime. They are joined by George Stone, a sharpshooting rookie, and Oscar Wallace, a bookkeeping Treasury agent who suggests that Capone can be prosecuted for tax evasion. The team becomes known as the Untouchables, because they cannot be bribed. Capone responds with violence, and the team must protect his bookkeeper to win the case. The film features a famous shootout on a staircase at Union Station.'),
    ('A Fish Called Wanda', 1988, 'Comedy', 'A group of London jewel thieves pull off a diamond robbery: the gang leader George, his stuttering, animal-loving accomplice Ken, and an American pair, the seductive con artist Wanda and her jealous, pseudo-intellectual lover Otto, who pose as brother and sister. Wanda and Otto betray George to the police, hoping to take the diamonds for themselves, but George has already moved the loot. Wanda tries to seduce George''s barrister, the repressed Archie Leach, to find out where the diamonds are, and Archie falls for her. Meanwhile, Ken tries to eliminate an elderly woman who witnessed the robbery, but keeps accidentally killing her small dogs instead. The farce of lies, jealousy and mistaken intentions builds to a chaotic finale at Heathrow Airport.'),
    ('Akira', 1988, 'Animation', 'In 2019, thirty-one years after a mysterious explosion destroyed Tokyo and triggered World War III, the rebuilt city of Neo-Tokyo is plagued by gang violence, terrorism and political corruption. Kaneda leads a gang of teenage bikers that includes his childhood friend Tetsuo, who is badly injured in a crash involving a strange child with psychic powers. Tetsuo is taken by the military to a secret government project, where he is subjected to experiments that awaken terrifying psychic abilities. As his powers grow beyond his control, Tetsuo becomes consumed by anger and resentment, and he sets out to find Akira, the mysterious being linked to the destruction of the old Tokyo. Kaneda, with the help of a resistance member named Kei, must find a way to stop him.'),
    ('Beetlejuice', 1988, 'Comedy', 'Adam and Barbara Maitland are a sweet, quiet couple who die in a car accident and return as ghosts to their beloved country home in Connecticut. According to the handbook for the recently deceased, they are now trapped in the house for the next 125 years. When the house is bought by the Deetz family from New York, who begin to remodel it in a garish modern style, the Maitlands try to scare them away but fail. Lydia Deetz, the family''s gothic teenage daughter, can see the ghosts and befriends them. Desperate, the Maitlands turn to Betelgeuse, a crude and chaotic bio-exorcist who promises to get rid of the living, but he has his own plans, including a scheme to marry Lydia and escape the afterlife.'),
    ('Big', 1988, 'Comedy', 'Josh Baskin is a twelve-year-old boy who is too short to go on a carnival ride in front of a girl he likes. Humiliated, he puts a coin into a fortune-telling machine called Zoltar and wishes he were big. The next morning he wakes up in the body of a thirty-year-old man. His mother does not recognize him and chases him away as an intruder, so Josh flees to New York City with the help of his best friend Billy. He gets a job at a toy company, where his childlike enthusiasm impresses the owner, Mr. MacMillan, during a famous duet on a giant floor piano, and leads to a quick promotion. Josh begins a romance with a coworker, Susan, but as he becomes absorbed in adult life, he realizes how much of his childhood he is missing.'),
    ('Coming to America', 1988, 'Comedy', 'Prince Akeem of the wealthy African kingdom of Zamunda is unhappy with his privileged life and with the arranged marriage his parents have planned for him on his twenty-first birthday. Wanting a wife who will love him for himself rather than for his title, he travels to New York with his friend and servant Semmi, choosing the borough of Queens because, he reasons, that is where a future queen would be found. Pretending to be poor students, they rent a run-down apartment, and Akeem takes a job at McDowell''s, a fast food restaurant that imitates McDonald''s. He falls in love with Lisa, the daughter of the restaurant''s owner, but she is dating a wealthy, arrogant heir. Eddie Murphy and Arsenio Hall each play several roles.'),
    ('Die Hard', 1988, 'Action', 'John McClane, a New York police officer, flies to Los Angeles on Christmas Eve hoping to reconcile with his estranged wife Holly, who has moved there for a job with the Nakatomi Corporation. While he is at the company''s Christmas party in the Nakatomi Plaza skyscraper, a group of heavily armed men led by the sophisticated Hans Gruber takes over the building and holds the employees hostage. McClane slips away barefoot and begins a one-man war against the intruders, communicating by radio with Sergeant Al Powell, a patrol officer waiting outside. While the police and the FBI bungle the response, McClane discovers that the so-called terrorists are actually thieves planning to steal six hundred and forty million dollars in bearer bonds from the building''s vault.'),
    ('My Neighbor Totoro', 1988, 'Animation', 'In 1950s rural Japan, a university professor moves with his two young daughters, Satsuki and Mei, to an old house in the countryside to be closer to their mother, who is recovering from an illness in a nearby hospital. The girls explore their new home and discover that it is inhabited by tiny soot sprites. Mei follows a small white creature into the forest and finds a large furry forest spirit sleeping inside a giant camphor tree, which she calls Totoro. The sisters befriend Totoro, who takes them on magical adventures, including flying through the night sky and riding the Catbus, a giant cat shaped like a bus. When worrying news arrives about their mother''s health, Mei sets off alone for the hospital, and Satsuki must ask Totoro for help to find her.'),
    ('Rain Man', 1988, 'Drama', 'Charlie Babbitt is a selfish, fast-talking Los Angeles car dealer in financial trouble. When his estranged father dies, Charlie learns that he has inherited only a classic Buick and some prize rose bushes, while the three-million-dollar estate goes to an unnamed beneficiary. He discovers that the money is going to a mental institution in Ohio, where his older brother Raymond, whom he never knew existed, has lived for years. Raymond is an autistic savant with extraordinary memory and mathematical abilities who depends on strict routines. Charlie takes Raymond away, hoping to win custody and the money, and because Raymond refuses to fly, they drive across the country. Along the way, Charlie uses Raymond''s abilities to win at blackjack in Las Vegas, and the brothers form a genuine bond.'),
    ('They Live', 1988, 'Sci-Fi', 'A drifter named Nada arrives in Los Angeles looking for work and finds a job at a construction site. He befriends a fellow worker, Frank, who takes him to a shantytown where homeless people live. Nada notices strange activity at a nearby church and discovers a hidden box of sunglasses. When he puts on a pair, he sees that the world is full of subliminal messages such as "Obey," "Consume" and "Conform," and that many members of the ruling class are actually skull-faced aliens. Realizing that the aliens are controlling humanity through a television signal, Nada joins a resistance movement to shut it down. The film is known for its satire of 1980s consumerism and for a famously long fistfight between Nada and Frank in an alley.'),
    ('Who Framed Roger Rabbit', 1988, 'Comedy', 'In 1947 Hollywood, cartoon characters known as toons live alongside humans and work as actors in animated films. Eddie Valiant, a down-on-his-luck private detective who has hated toons since one killed his brother, is hired by studio head R.K. Maroon to photograph Jessica Rabbit, the glamorous wife of cartoon star Roger Rabbit, who is suspected of flirting with Marvin Acme, the owner of Toontown. When Acme is found murdered, Roger becomes the prime suspect and goes into hiding, begging Eddie to clear his name. The sinister Judge Doom, who has created a toxic substance called the Dip that can kill toons, leads the manhunt. Eddie uncovers a conspiracy involving Acme''s missing will, the future of Toontown and the Los Angeles streetcar system.'),
    ('Back to the Future Part II', 1989, 'Sci-Fi', 'Picking up right where the first film ended, Doc Brown takes Marty McFly and his girlfriend Jennifer to 2015 to stop their future son from getting into trouble with Griff Tannen, the grandson of Biff. While in the future, Marty buys a sports almanac listing the results of decades of sporting events, but Doc throws it away. The elderly Biff overhears and steals the DeLorean, traveling back to 1955 to give the almanac to his younger self. When Marty and Doc return to 1985, they find a nightmarish alternate reality in which Biff has become a rich and powerful tyrant, and Marty''s father George is dead. They must return to 1955 to recover the almanac without running into the versions of themselves from the first adventure.'),
    ('Batman', 1989, 'Action', 'In Gotham City, billionaire Bruce Wayne, who witnessed the murder of his parents as a child, fights crime at night as Batman, a vigilante whose existence is still regarded by many as a rumor. Photojournalist Vicki Vale and reporter Alexander Knox investigate the stories about the mysterious bat-man, and Vale begins a romance with Wayne. Meanwhile, mob enforcer Jack Napier is set up by his boss and falls into a vat of chemicals during a fight with Batman, emerging with white skin, green hair and a permanent grin. Calling himself the Joker, he takes over the mob and terrorizes the city, poisoning cosmetics with a deadly toxin that leaves victims laughing. Batman discovers that the Joker is the young thug who killed his parents years ago.'),
    ('Dead Poets Society', 1989, 'Drama', 'In 1959, John Keating, a former student, returns to the elite Welton Academy, a conservative boarding school in Vermont, as the new English teacher. His unconventional teaching methods, such as having students stand on their desks and tear the introduction out of their poetry textbook, inspire them to think for themselves and to "seize the day." A group of students led by Neil Perry revives the Dead Poets Society, a secret club Keating belonged to as a student, meeting in a cave to read poetry. Neil discovers a passion for acting and wins a role in a production of A Midsummer Night''s Dream, against the wishes of his domineering father, who wants him to become a doctor. The conflict ends in tragedy, and the school looks for someone to blame.'),
    ('Do the Right Thing', 1989, 'Drama', 'On the hottest day of the summer in the Bedford-Stuyvesant neighborhood of Brooklyn, Mookie, a young Black man, works as a delivery man for Sal''s Famous Pizzeria, owned by Sal, an Italian-American, who runs it with his two sons. The neighborhood is a mix of different ethnic groups, and tensions rise as the heat builds throughout the day. Buggin'' Out, a local activist, demands that Sal include photos of Black people on the pizzeria''s Wall of Fame, which only shows Italian-Americans, and tries to organize a boycott. Radio Raheem, who carries a large boombox playing Public Enemy''s "Fight the Power," joins him. When the conflict explodes at closing time, the police arrive, and a tragedy sparks a riot.'),
    ('Field of Dreams', 1989, 'Fantasy', 'Ray Kinsella, an Iowa corn farmer, hears a mysterious voice in his cornfield whispering, "If you build it, he will come." He interprets the message as an instruction to build a baseball diamond in his field, even though it threatens his family''s finances. After he builds it, the ghost of Shoeless Joe Jackson, the legendary player banned from baseball after the 1919 Black Sox scandal, appears to play, followed by other long-dead players. The voice gives Ray further messages, leading him on a journey to Boston to find a reclusive writer, Terence Mann, and to Minnesota to search for a doctor who played only one game in the major leagues. Ray''s journey ultimately leads to an emotional reconciliation with his late father.'),
    ('Glory', 1989, 'War', 'During the American Civil War, Captain Robert Gould Shaw, a young Union officer from a wealthy Boston abolitionist family, is given command of the 54th Massachusetts Infantry Regiment, one of the first all-Black units in the Union Army. Shaw faces prejudice from the Army itself, which denies the soldiers shoes and uniforms and pays them less than white troops. The recruits include Trip, a defiant runaway slave, Rawlins, a wise former gravedigger, and Thomas, an educated childhood friend of Shaw. Under Shaw''s leadership, the regiment proves its courage in combat and earns the respect of other units. The film culminates in the regiment''s heroic and costly assault on Fort Wagner in South Carolina in 1863.'),
    ('Indiana Jones and the Last Crusade', 1989, 'Adventure', 'In 1938, Indiana Jones learns that his father, Henry Jones Sr., a medieval scholar obsessed with finding the Holy Grail, has disappeared in Venice while searching for the legendary cup. With his father''s diary, which contains decades of research, Indy travels to Venice and meets Dr. Elsa Schneider, an Austrian art historian. They discover clues in catacombs beneath a library and are attacked by a secret brotherhood sworn to protect the Grail. Indy rescues his father from a castle on the Austrian border, but learns that Elsa is working with the Nazis, who are also looking for the Grail. Father and son race across Germany and the Middle East, facing a tank battle and three deadly trials to reach the Grail before their enemies.'),
    ('National Lampoon''s Christmas Vacation', 1989, 'Comedy', 'Clark Griswold wants to give his family a perfect, old-fashioned Christmas at their suburban Chicago home. He invites both sets of grandparents to stay with them, and he covers his house with twenty-five thousand twinkling lights. Everything goes wrong: the lights refuse to turn on, a squirrel hides in the Christmas tree, and his wife''s cousin Eddie arrives uninvited with his family in a run-down RV. Clark is counting on his yearly Christmas bonus to build a swimming pool, but when he receives a membership in a jelly-of-the-month club instead, he snaps. Eddie kidnaps Clark''s stingy boss, Frank Shirley, and brings him to the house, leading to a chaotic raid by a police SWAT team.'),
    ('The Little Mermaid', 1989, 'Animation', 'Ariel, the sixteen-year-old daughter of King Triton, ruler of the undersea kingdom of Atlantica, is fascinated by the human world and collects objects from shipwrecks. When she saves Prince Eric from drowning after a storm, she falls in love with him. Her father forbids any contact with humans, and in anger he destroys her collection. Desperate, Ariel makes a deal with Ursula, the sea witch: she will become human for three days in exchange for her voice. To remain human, she must receive the kiss of true love from Eric before the sun sets on the third day. With the help of her friends, the crab Sebastian, the fish Flounder and the seagull Scuttle, she tries to win the prince''s heart while Ursula schemes against her.'),
    ('When Harry Met Sally...', 1989, 'Romance', 'In 1977, Harry Burns and Sally Albright, two recent University of Chicago graduates, share a long drive to New York City. During the trip, they argue about everything, and Harry claims that men and women can never be friends because sex always gets in the way. They part ways and meet again by chance five years later. When they meet a third time, both recently separated from long-term partners, they become close friends, spending hours talking on the phone and spending holidays together. They try to set each other up with their best friends, who fall in love with each other instead. The film is punctuated by interviews with elderly couples telling the story of how they met, and features a famous scene in a New York deli.')
) AS v(title, release_year, genre, description)
ON CONFLICT (title, release_year) DO NOTHING;
